    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    lines = set()
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            color = row[0]
            if any(v != color for rr, vals in enumerate(grid) if rr != r for v in vals):
                lines.add(('r', r))
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) == 1:
            color = vals[0]
            if any(grid[r][cc] != color for r in range(h) for cc in range(w) if cc != c):
                lines.add(('c', c))
    for kind, i in lines:
        if kind == 'r':
            out[i] = [2] * w
        else:
            for r in range(h):
                out[r][i] = 2
    return out
'''
